    velocity (positive counter-clockwise): dx·vy and dy·vx. -/
def crossPlus : Term := .mul radiusX (.measure "kin_velocity" [aX, .lit "y"])
def crossMinus : Term := .mul radiusY (.measure "kin_velocity" [aX, .lit "x"])

